"use strict";(globalThis.webpackChunksanctuary_amongst_the_starts=globalThis.webpackChunksanctuary_amongst_the_starts||[]).push([[4322],{2375(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>i,metadata:()=>s,toc:()=>h});const s=JSON.parse('{"id":"world-information/locations/outer-system/saturn","title":"Saturn","description":"---","source":"@site/docs/world-information/locations/outer-system/saturn.md","sourceDirName":"world-information/locations/outer-system","slug":"/world-information/locations/outer-system/saturn","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/outer-system/saturn","draft":false,"unlisted":false,"editUrl":"https://github.com/kaelynj/sanctuary-amongst-the-stars/docs/world-information/locations/outer-system/saturn.md","tags":[],"version":"current","frontMatter":{},"sidebar":"loreSidebar","previous":{"title":"Outer System Fringe","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/outer-system/outer-system-fringe"},"next":{"title":"Titan","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/outer-system/titan"}}');var a=t(4848),o=t(8453);const i={},r="Saturn",l={},h=[{value:"Ringers",id:"ringers",level:2},{value:"Gas Mining",id:"gas-mining",level:2},{value:"Saturnian Settlements",id:"saturnian-settlements",level:2},{value:"Kronos Cluster",id:"kronos-cluster",level:3},{value:"Pandora",id:"pandora",level:3},{value:"Meathab",id:"meathab",level:3},{value:"Bright (Tethys)",id:"bright-tethys",level:3},{value:"Phelan&#39;s Recourse",id:"phelans-recourse",level:3},{value:"Salah",id:"salah",level:3},{value:"Twelve Commons (Epimetheus and Janus)",id:"twelve-commons-epimetheus-and-janus",level:3},{value:"Profunda (Enceladus)",id:"profunda-enceladus",level:3}];function d(e){const n={em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"saturn",children:"Saturn"})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Posted by:"})," ",(0,a.jsx)(n.em,{children:"Isabella Dandolo, Firewall Proxy"})]}),"\n",(0,a.jsx)(n.p,{children:"The smaller of our system\u2019s two gas giants.\xa0 Jupiter\u2019s cool sibling.\xa0 Everyone here is free: there\u2019s no oppressive political bloc telling you how to run your life every minute of every day.\xa0 There\u2019s room to spare for its more than 80 million transhuman inhabitants, all of whom can express themselves as they see fit.\xa0 There are major centers of learning for those who want to expand their mind, pharmaceuticals for the same, employment opportunities, space to hide, space to party, and space to live and love.\xa0 Saturn\u2019s famous wide, thin rings stretch from 7,000 km above the clouds, to nearly 80,000 km. More than 60 moons and moonlets orbit Saturn, including Titan, the only satellite in the Solar System with a thick natural atmosphere."}),"\n",(0,a.jsx)(n.h2,{id:"ringers",children:"Ringers"}),"\n",(0,a.jsx)(n.p,{children:"Saturn\u2019s rings are the primary source of water in the system and a great place to go to be alone and contemplate the beauty of the universe.\xa0 Ringers forego habs and use vacuum-tolerant morphs to live here, going months without seeing anyone else.\xa0 Some ringers are here to hide, but most are just solitary; they look out for each other and protect each other\u2019s privacy."}),"\n",(0,a.jsx)(n.h2,{id:"gas-mining",children:"Gas Mining"}),"\n",(0,a.jsx)(n.p,{children:"Mining the clouds is also a major business.\xa0 Contractors operate automated skimmers or navigate harvester aerostats to extract methane and ammonia from the top of the atmosphere.\xa0 Deeper operations dip into Saturn\u2019s depths to return with volatiles and helium-3.\xa0 Orbital refineries run by hypercorps like Volkov process the gases and ship them to habitats around the system."}),"\n",(0,a.jsx)(n.h2,{id:"saturnian-settlements",children:"Saturnian Settlements"}),"\n",(0,a.jsx)(n.h3,{id:"kronos-cluster",children:"Kronos Cluster"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Habitat Type:"})," Cluster"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Allegiance:"})," Independent (Anarchist/Criminal/Ultimate)"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Kronos started as an Extropian and anarchist settlement made of tin-can modules and grew to the bursting point after the Fall, when it accepted hundreds of thousands of refugees from Earth. The original settlers found themselves at odds with newly-formed criminal syndicates, and Kronos became a hotbed of the quasi-legal and morally questionable."}),"\n",(0,a.jsx)(n.p,{children:"Things deteriorated, and the Extropians formed the Kronos Port Authority (KPA), which brought in Ultimate mercenaries to enforce their rules. The Ultimates took over the KPA, and have now forces a detente across the station."}),"\n",(0,a.jsx)(n.p,{children:"Kronos is now a patchwork of armed neighborhoods. Tourists are drawn to the vices offered, and the KPA makes bank on offering them protective services. The KPA runs a business license protection racket to keep the gangs from getting out of hand. The anarchists keep to themselves, but sometimes conflicts flare up with neighboring groups."}),"\n",(0,a.jsx)(n.h3,{id:"pandora",children:"Pandora"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Habitat Type:"})," Beehive"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Allegiance:"})," Independent (Gatekeeper)"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Saturn\u2019s outermost shepherd moon is also one of the most studied and trafficked places in the Solar System. The site of the first discovered pandora gate, Pandora has a single major settlement: Gateway. Run by the Gatekeeper Corporation, once a subsidiary of the Commonwealth of Titan but now autonomous, Gateway is the major hub between here and there. Almost every hypercorp and government with any influence has representation here. This mix makes the station a steaming cauldron of cultures, ideologies, hopes, dreams, and ruthless ambitions."}),"\n",(0,a.jsxs)(n.p,{children:["The scum barge ",(0,a.jsx)(n.em,{children:"Lost in Neverwhere"})," is an excellent supply point for sentinels who need to acquire discrete items. It maintains a semi-permanent orbit around the moonlet, moving only when station security gets sick of their antics."]}),"\n",(0,a.jsx)(n.h3,{id:"meathab",children:"Meathab"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Habitat Type:"})," Biological"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Allegiance:"})," Independent"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"When post-Fall postmodernism is no longer enough, artists create projects like Turn Yourself Into a Giant Mass of Space Meat for Art! MeatHab is a living habitat made primarily of vat-grown bacon. Originally intended to be temporary, it attracted a following of anarchists, scum, researchers, and weirdos that squatted the station to bask in the oddness of its veinous, skin-covered corridors. It has even spawned its own religious cult, the Acolytes of Living Meat. By all indications, the mysterious original designer is still present, occasionally playing pranks on its inhabitants."}),"\n",(0,a.jsx)(n.h3,{id:"bright-tethys",children:"Bright (Tethys)"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Habitat Type:"})," Hamilton Cylinder"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Allegiance:"})," Independent (Acumenic)"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"What happens when you stick genius-level egos together in a single hab, provide for their basic needs, and turn them loose on whatever strikes their fancy? You get Bright, a joint hypercorp experiment in commodifying intelligence. Well, it was a joint project until Acumenic pulled a hostile takeover, even pushing Cognite's project lead out an airlock. Now Acumenic is struggling to assert control over the station. At least one part of the habitat has been seized by a group of self-made sociopaths and closed off to outsiders. Bright is housed on a work-in-progress Hamilton cylinder constructed from Tethys\u2019 moon Telesto."}),"\n",(0,a.jsx)(n.h3,{id:"phelans-recourse",children:"Phelan's Recourse"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Habitat Types:"})," Swarm"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Allegiance:"})," Scum"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Known colloquially as Phelan's, this scum flotilla is a waystation between Saturnian civilization and the wilderness beyond; a constant, free-wheeling party where you're just as likely to find yourself blasted out an airlock as you are chasing a high with some of the finest Fall refugees you'll ever meet. While Phelan's is a fine place to pick up some of the greatest mind-altering substances you can ingest, its best export is Phelan's Ma, hands-down the best whiskey in the galaxy unless you happen to have a bottle of 21-year-old PortWood Balvenie. Phelan's swarm cycles between Saturn's moons, making it an excellent place to score intel and make connections."}),"\n",(0,a.jsx)(n.h3,{id:"salah",children:"Salah"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Habitat Types:"})," Hamilton Cylinder"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Allegiance:"})," Independent (Contested)"]}),"\n"]}),"\n",(0,a.jsxs)(n.p,{children:["Salah was conceived by the Al Thani family of Qatar, who heavily financed various efforts to expand into space. Originally intended as a grandiose display of wealth and power, Salah is now seen by many Muslims as an opportunity to bring the ",(0,a.jsx)(n.em,{children:"ummah"})," together again and give them a place of their own to call home. However, the Al Thani family is working hard to open Salah to Consortium hypercorps, offering them a foothold in the outer system. Already their designs have run counter to the community's wishes."]}),"\n",(0,a.jsx)(n.p,{children:"Salah is a place of faith and tolerance. While many of them follow the teachings of the Prophet, a great many Hindus, some Christians, and some Jewish refugees have been given quarter here. Salah was designed to inspire. Vast parks and green spaces combine with architecture meant to emulate everything from the Hagia Sophia to the Al Haram to Canterbury Cathedral. It is hard not to stand within Salah and feel awe."}),"\n",(0,a.jsx)(n.h3,{id:"twelve-commons-epimetheus-and-janus",children:"Twelve Commons (Epimetheus and Janus)"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Habitat Types:"})," Beehive/Cluster/Spheroid/Torus"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Allegiance:"})," Anarchist"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Twelve Commons is a neighborhood of habitats that reside on or near the co-orbital path of the moonlets Epimetheus and Janus. There are now many more than twelve of the original anarchist collectives that formed Twelve Commons. The entire settlements occupies a cloud spread out over 20,000 kilometers. It\u2019s a refuge for scientists, artists, engineers, and writers."}),"\n",(0,a.jsx)(n.p,{children:"Notable communities include the Do-It-Yourself Shipyards, where the technicians and automated construction facilities delight in taking your ship design from plans to reality; Janus Commons, a 900,000-person habitat full of research labs and experimental theater productions; Long Haul, a collective devoted to liberating infugees and indentures and giving them new morphs; and Small Majesties, a collective of nano-artists."}),"\n",(0,a.jsx)(n.h3,{id:"profunda-enceladus",children:"Profunda (Enceladus)"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Habitat Type:"})," Beehive"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Allegiance:"})," Extropian"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Profunda is the largest settlement on Enceladus and famous across the system. On-station government is nearly nonexistent; business is conducted with Extropian legal contracts. The Profunda Corporation is the key interest in mining and refining operations, but it is not the only game in town. Profunda, however, is best known for their premier genetic designers and morph artists. They create everything from custom morphs to neogenetic and chimeric creatures like the winged smart cats popular around the Saturn system. Profunda's Glitter Bloc dominates the market in luxury morph models, providing sleeves to some of the most notorious metacelebrities and socialites."})]})}function c(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>i,x:()=>r});var s=t(6540);const a={},o=s.createContext(a);function i(e){const n=s.useContext(o);return s.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),s.createElement(o.Provider,{value:n},e.children)}}}]);